+/**
+ * Formatea centavos como pesos mexicanos: 150742 → "$1,507.42".
+ * Solo formato: no calcula impuestos ni redondea montos; eso lo hace el servidor.
+ * @param cents monto en centavos, tal como viene en `Money.amountCents`
+ */
+export const formatMXN = (cents: number) => mxnFormatter.format(cents / 100);
